import React from 'react';

const Properties = () => {
  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold mb-6">Available Properties</h1>
      <div className="text-center py-12">
        <p className="text-gray-600 text-lg">Properties listing will be implemented here.</p>
        <p className="text-gray-500 mt-2">This will show all available properties with search and filter functionality.</p>
      </div>
    </div>
  );
};

export default Properties;
